/* Client-side search over the index generated by build.py. */
(function () {
  "use strict";

  var index = window.SEARCH_INDEX || [];
  var input = document.getElementById("search-page-input");
  var count = document.querySelector("[data-search-count]");
  var list = document.querySelector("[data-search-results]");
  if (!input || !list) return;

  // Common words people use that do not appear verbatim in the content.
  var SYNONYMS = {
    urgent: "tatkaal", tatkal: "tatkaal", renewal: "re-issue", renew: "re-issue", reissue: "re-issue",
    cost: "fee", price: "fee", charges: "fee", status: "track", pcc: "police clearance",
    kid: "child", kids: "child", baby: "child", minor: "child", psk: "passport seva kendra"
  };

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function terms(q) {
    return q.toLowerCase().split(/[^a-z0-9₹-]+/).filter(function (t) { return t.length > 1; })
      .map(function (t) { return SYNONYMS[t] || t; });
  }

  function score(page, words) {
    var title = page.title.toLowerCase();
    var desc = page.description.toLowerCase();
    var heads = page.headings.join(" ").toLowerCase();
    var text = page.text.toLowerCase();
    var total = 0;
    for (var i = 0; i < words.length; i++) {
      var w = words[i];
      var s = 0;
      if (title.indexOf(w) !== -1) s += 10;
      if (heads.indexOf(w) !== -1) s += 5;
      if (desc.indexOf(w) !== -1) s += 3;
      if (text.indexOf(w) !== -1) s += 1;
      if (!s) return 0; // every word must appear somewhere
      total += s;
    }
    return total;
  }

  var q = new URLSearchParams(window.location.search).get("q") || "";
  input.value = q;
  if (!q.trim()) {
    count.textContent = "Enter a word or phrase, for example ‘tatkaal fee’.";
    return;
  }

  var words = terms(q);
  var results = index.map(function (p) { return { page: p, score: score(p, words) }; })
    .filter(function (r) { return r.score > 0; })
    .sort(function (a, b) { return b.score - a.score; });

  count.textContent = results.length + (results.length === 1 ? " result" : " results") + " for ‘" + q + "’";
  document.title = q + " – Search – Passport Seva";
  list.innerHTML = results.map(function (r) {
    return '<li class="news-list__item"><p class="news-list__title"><a href="' + r.page.url + '">' +
      escapeHtml(r.page.title) + "</a></p><p>" + escapeHtml(r.page.description) + "</p></li>";
  }).join("");
  if (!results.length) {
    list.innerHTML = '<li class="news-list__item"><p>Try different words, or go to <a href="help.html">Help</a> or call <a href="tel:18002581800">1800-258-1800</a>.</p></li>';
  }
})();
